        runHealth: (forNodeId) => runHealth($, forNodeId),
        queueMemoryCheck: (expectedTurns, goalId, title, goalIds) => queueMemoryCheck($, expectedTurns, goalId, title, goalIds),
        writeClaimDirect: () => writeClaimDirect($),
