        appendLines: (path, lines, known) => appendLines($, path, lines, known),
        addGoalEntry: (entry) => addGoalEntry($, entry),
        readPlanDocument: (planPath) => readPlanDocument($, planPath),
        completeRootByGoalDone: async (named, note) => {
