{
  "name": "personas",
  "description": "PIANO-esque cognitive layer: persona-keyed state, heartbeat liveness, controller with classify/actuate",
  "author": {
    "name": "Dreamed up by Scott Applefeld, built by Claude"
  },
  "types": "./hooks/personas.d.ts",
  "userConfig": {
    "persona": {
      "type": "string",
      "default": "default",
      "title": "Persona",
      "description": "Which persona this session claims at start (e.g. 'default', 'dev'). Defaults to 'default' when unset."
    },
    "heartbeatMs": {
      "type": "number",
      "default": 30000,
      "title": "Heartbeat interval (ms)",
      "description": "How often the owner refreshes its heartbeat (ms). Default 30s."
    },
    "staleAfterMs": {
      "type": "number",
      "default": 90000,
      "title": "Stale threshold (ms)",
      "description": "How long before a heartbeat is considered stale (ms). Default 90s."
    },
    "memoryGateDiscardPercent": {
      "type": "number",
      "default": 90,
      "title": "Memory gate discard floor (percent)",
      "description": "The confidence floor, 50 to 100, at which Jev's own discard probability skips the memory-kind Haiku classify and distill calls outright, on a dev-split turn. Acts only where memory-kind is named in jevLive; otherwise this setting does nothing. Default 90."
    },
    "controllerTickMs": {
      "type": "number",
      "default": 30000,
      "title": "Controller tick (ms)",
      "description": "How often the controller evaluates the goal (ms). Default 30s."
    },
    "nudgeFloorMs": {
      "type": "number",
      "default": 300000,
      "title": "Nudge floor (ms)",
      "description": "Minimum time between nudges (ms). Default 5min."
    },
    "nudgeIdleMs": {
      "type": "number",
      "default": 120000,
      "title": "Nudge idle gate (ms)",
      "description": "Session must be idle this long before a nudge is eligible (ms). Default 2min."
    },
    "healthTimeoutMs": {
      "type": "number",
      "default": 60000,
      "title": "Health timeout (ms)",
      "description": "Timeout for the health probe (ms). Default 60s, cap 120s."
    },
    "healthCommand": {
      "type": "string",
      "default": "",
      "title": "Health command",
      "description": "The command the controller runs in the session's working directory after a goal completes, such as 'node scripts/health.js'. Exit 0 logs health_green, and any other exit, a timeout or a failure to start logs health_red, which reaches the next turn. The text is split on whitespace into a program and its arguments and run with no shell, so quoting, pipes and redirection do not work: for anything more, point it at a script, such as one run by node. Empty by default, which runs nothing."
    },
    "gitProbeMs": {
      "type": "number",
      "default": 120000,
      "title": "Git probe interval (ms)",
      "description": "How often the git probe runs (ms). Default 120s, cap 300s."
    },
    "askOperatorWaitMs": {
      "type": "number",
      "default": 3600000,
      "title": "Ask timeout (ms)",
      "description": "How long a blocking ask holds the controller before the timeout clears its hold and leaves the ask open, so work proceeds on the worker's recommendation (ms). 0 means no timeout. Default 60min."
    },
    "askReraiseWindowMs": {
      "type": "number",
      "default": 900000,
      "title": "Ask re-raise window (ms)",
      "description": "How long after a blocking ask opens before re-raising it to the operator's thread (ms). A non-blocking ask is never re-raised. Default 15min."
    },
    "askReaskSuppressMs": {
      "type": "number",
      "default": 600000,
      "title": "Ask re-ask suppress window (ms)",
      "description": "How long after an ask closes, or the operator's reply or the timeout lifts its hold, before the worker can re-open the same question on the same entry, by ask_open or an ASK: line (ms). Default 10min."
    },
    "channelRecordWindow": {
      "type": "number",
      "default": 50,
      "title": "Channel record window (count)",
      "description": "How many closed inbox/reply records the shared store keeps per persona before rolling the rest to .agentic-channel.jsonl. Open asks are never rolled by this window. Default 50."
    },
    "arming": {
      "type": "string",
      "default": "off",
      "title": "Arming tier",
      "description": "off, reader or owner. off registers the guards and after hooks and no tool or claim, and one timer, the compaction pass's (a plain chat session). reader registers agentic_identity/agentic_say/agentic_inbox/fleet_status only, with no goal-tree tool and no ownership. owner is the full worker/coordinator shape. A supervisor launch always sets owner."
    },
    "coordinatorPersona": {
      "type": "string",
      "default": "coordinator",
      "title": "Coordinator persona name",
      "description": "The one persona name the inbox gates treat as the coordinator: its owner may address any persona, and any named persona owner may address it. A configured name of 'default' is refused and falls back to 'coordinator'."
    },
    "architectPersona": {
      "type": "string",
      "default": "",
      "title": "Architect persona name",
      "description": "The persona name this file offers as the architect: the design seat the coordinator routes design asks to, and the seat whose own launch receives the architect charter. The supervisor reads it to build that charter and the coordinator's design clause. The plugin reads it for the inbox gates: any named persona owner may address it, and its owner may answer a persona whose owner's record to it is delivered or answered, an answer that is delivered even if the architect resolves that record after sending it. The plugin reads a name of 'default', or the coordinator's own name, as no architect. Where this file names no architect, the fleet has none, no design-escalation clause is built, and both of those inbox lines stay closed."
    },
    "liaisonPersona": {
      "type": "string",
      "default": "",
      "title": "Liaison persona name",
      "description": "The persona name this file offers as the liaison: the seat several people talk with in one thread, which shapes their asks into briefs for the architect and relays status from the coordinator, and whose own launch receives the liaison charter. The supervisor reads it to build that charter and the coordinator's clause answering the liaison's status asks. The plugin reads nothing from it, since the liaison sends as a named persona and is reached as one. The supervisor refuses a name of 'default', the coordinator's or the architect's own name, and a liaison named in a file that names no architect. Where this file names no liaison, the fleet has none and neither text is built."
    },
    "fleetRoster": {
      "type": "string",
      "default": "",
      "title": "Fleet roster path",
      "description": "The roster file the fleet reading uses: a JSON array of persona entries, each naming a persona, its working directory, optionally its run directory, and whether the fleet runs it. The fleet_status tool reads it on demand, and the coordinator persona's controller tick reads it every tick to watch each roster persona's health class. Left unset, fleet_status reports that it has no roster to read and the tick's watcher stays silent."
    },
    "jevMode": {
      "type": "string",
      "default": "shadow",
      "title": "Jev shadow mode",
      "description": "off or shadow, and shadow is the default. shadow has the decision seam ask Jev its questions and write each answer to the decision journal. A question jevLive names, the two memory questions, and the compaction question under a live compactionPass act on the answer, and every other question acts on nothing it gets back. off makes no such call and writes no journal line. The supervisor refuses any other value rather than writing it, so a typo stops that launch instead of quietly disabling the seam."
    },
    "compactionPass": {
      "type": "string",
      "default": "live",
      "title": "Compaction pass",
      "description": "off, shadow or live, and live is the default. shadow has the module ask Jev on a timer, the heartbeat in an armed session and a timer of its own in an unarmed one, whether each old tool result is kept, cut or dropped, build a plan from those answers, and write to the decision journal what the plan would have kept at each automatic compaction and once per idle stretch past the cache life. It changes no message. live plans the same way and then acts: at an automatic compaction or its precompute it sends the plan's cut message list down to the engine's summary where the plan covers the transcript and keeps each call beside its result, and otherwise the summary runs over the whole transcript. At an expired cache it starts one marked compaction per idle stretch, only where the plan would drop at least 20,000 tokens, and that compaction cuts or skips and never summarizes. off asks nothing and writes nothing. Any other value is read as off, with one decision saying so. Under jevMode off a pass that is not off asks nothing, writes one compaction_pass_disabled line per session, armed or not, and writes no line at a compaction."
    },
    "guards": {
      "type": "string",
      "default": "live",
      "title": "Before-tool guards",
      "description": "off, shadow or live, and live is the default. shadow has the module's tool.call hook run every registered before-tool guard on each call, write each verdict to the decision journal as a guard_verdict line and a guard_shadow line, and let the call run. The guard_shadow line's command verdict reads deny only on a refusal phrase no command hook in the current kit writes. live returns a guard's deny as the call's result and refuses a call whose guard failed, naming the guards the call matched. off runs no guard. The after-call hooks run whatever the value. Any other value is read as live, so a misspelt value disarms nothing and keeps the memq grant answering, with one decision saying so."
    },
    "jevLive": {
      "type": "string",
      "default": "controller-decision,turn-score,memory-kind,turn-disposition",
      "title": "Jev live questions",
      "description": "Comma-separated question-set ids, each one of PROMOTABLE_SET_IDS, naming which question may read Jev's live answer through liveAsk instead of always shadowing it. The default names controller-decision, turn-score, memory-kind and turn-disposition. A configured value replaces the default whole, so an empty value makes no question live. An id outside the promotable set is dropped, logged as one jev_live_invalid decision naming it."
    },
    "restartRecap": {
      "type": "string",
      "default": "auto",
      "title": "Automatic restart recap",
      "description": "auto or skill, and auto is the default. auto runs bin/restart-recap.mjs at the supervisor's priming turn and injects its digest as a [RESTART RECAP] block, only where the previous session's last record is under 24 hours old and either the persona has an active goal or the operator wrote within 6 hours. skill runs nothing at launch, leaving the recap to the restart-recap skill. Any other value reads as auto at the plugin's own read. A supervisor launch given RESTART_RECAP outside that pair stops rather than writing it."
    },
    "reconcileEveryMs": {
      "type": "number",
      "default": 14400000,
      "title": "Reconciliation cadence (ms)",
      "description": "How long between the [RECONCILE] prompts the coordinator persona's controller tick submits, which are the only trigger for the kit Coordinator seat's reconciliation pass. Default 4 hours, that seat's own cadence: the claim probe's window is one full cadence and the registry prune's staleness test is twice it, so a shorter run of either could fire nothing a four-hourly run misses. A value at or below zero takes the default, since it would otherwise be satisfied by every tick."
    },
    "supervisorMailbox": {
      "type": "string",
      "default": "",
      "title": "Supervisor mailbox path",
      "description": "The mailbox file the supervisor that launched this session writes, <rundir>/mailbox.jsonl. The controller tick reads it and writes mailbox.ack.jsonl beside it: a probe is acknowledged with no turn spent, and a shutdown request is delivered once as a turn opening [SUPERVISOR id=<id>]. The supervisor writes this; left unset, as in an interactive session, the tick reads no mailbox."
    },
    "heartbeatPath": {
      "type": "string",
      "default": "",
      "title": "Heartbeat sidecar path",
      "description": "The absolute path of the working directory's heartbeat sidecar, the record of which session holds each persona. The supervisor writes the same path it reads, so the session stamps that file wherever its shell has moved. Left unset, the session stamps .agentic-heartbeat.json in the directory it was launched in."
    },
    "supervisorHeartbeatPath": {
      "type": "string",
      "default": "",
      "title": "Own heartbeat file path",
      "description": "The heartbeat file only this session writes, <rundir>/heartbeat.json, stamped with its session id, lastSeen and turnStartedAt on every heartbeat tick. It is the heartbeat the supervisor's liveness verdict reads. The supervisor writes this; left unset, no such file is written."
    },
    "redactor": {
      "type": "boolean",
      "default": true,
      "title": "Transcript redactor",
      "description": "Whether the redactor hides secrets from the transcript: a value a tool prints, a prompt carries, a context block holds or a subagent task quotes is swapped for a placeholder before the model reads it, the real value is restored only inside Bash, PowerShell, Write, Edit, MultiEdit and NotebookEdit, in a call that writes no store, and a store surface carrying a raw secret is refused. true by default. false passes every event through untouched."
    },
    "credentialFiles": {
      "type": "string",
      "default": "",
      "title": "Credential files",
      "description": "A comma-separated list of absolute paths whose secrets the redactor hides from session start. A file whose name ends in .env contributes the value of every line whose key is KEY, TOKEN, SECRET, PASSWORD, PASS or PWD, or ends in an underscore and one of them; any other file contributes its whole trimmed content. A missing or unreadable file contributes nothing and is logged once. Empty by default, which seeds nothing from this setting."
    }
  }
}

